require_once __DIR__ . '/../config/page_auth.php';
imcRequirePageAccess('depenses.reconcile', null, $pdo ?? null);
?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Reprise des dépenses historiques — Clarodaro</title>
<style>
:root{font-family:system-ui,sans-serif;color:#172033;background:#f1f5f9}*{box-sizing:border-box}body{margin:0}
header{background:#12355b;color:#fff;padding:1.25rem clamp(1rem,4vw,3rem)}main{max-width:1100px;margin:1.5rem auto;padding:0 1rem 3rem}
.card{background:#fff;border-radius:12px;padding:1.25rem;margin:1rem 0;box-shadow:0 3px 12px #0f172a12}
h1{margin:.1rem 0;font-size:1.5rem}h2{margin-top:0;color:#12355b;font-size:1.15rem}.notice{padding:.85rem 1rem;border-left:4px solid #2563eb;background:#eff6ff;border-radius:6px}
.warning{border-color:#d97706;background:#fffbeb}.error{border-color:#dc2626;background:#fef2f2}.success{border-color:#15803d;background:#f0fdf4}
button,select{font:inherit;padding:.65rem .8rem;border:1px solid #cbd5e1;border-radius:7px}button{cursor:pointer;background:#12355b;color:white;border-color:#12355b;font-weight:650}button:disabled{opacity:.45;cursor:not-allowed}
button.secondary{background:white;color:#12355b}.record{border:1px solid #dbe3ee;border-radius:9px;padding:1rem;margin:.75rem 0}.meta{color:#475569;font-size:.92rem}
.actions{display:flex;gap:.6rem;flex-wrap:wrap;margin-top:.75rem}.row{display:grid;grid-template-columns:minmax(0,1fr) minmax(220px,320px);gap:1rem;align-items:center}
label{display:block;font-weight:600;margin-bottom:.35rem}select{width:100%;background:#fff}.muted{color:#64748b}#status{white-space:pre-wrap}@media(max-width:650px){.row{grid-template-columns:1fr}}
</style></head><body>
<header><h1>Reprise contrôlée des dépenses historiques</h1><p>Clarodaro · Accès réservé au PDG</p></header><main>
<section class="card"><h2>1. Sauvegarder la source historique</h2>
<p>Les anciennes dépenses sont lues depuis le coffre sécurisé de ce navigateur. Téléchargez et vérifiez une sauvegarde complète avant tout import. La source locale ne sera ni supprimée ni modifiée.</p>
<div class="notice warning" id="backupNotice">Sauvegarde non confirmée : les imports restent désactivés.</div>
<div class="actions"><button id="exportBackup" type="button">Télécharger la sauvegarde JSON</button>
<label style="display:flex;gap:.5rem;align-items:center;font-weight:500"><input id="confirmBackup" type="checkbox" disabled> J’ai vérifié le fichier téléchargé.</label></div></section>
<section class="card"><h2>2. Rapprocher chaque dépense</h2>
<p class="muted">Chaque dépense doit être associée explicitement à une année scolaire PostgreSQL. Aucun rapprochement automatique ni remplacement de valeur.</p>
<p id="summary" class="muted">Chargement du coffre et des références PostgreSQL…</p><div id="status" role="status" aria-live="polite"></div><div id="records"></div></section>
<div class="actions"><button class="secondary" type="button" onclick="location.href='PDG.html'">Retour au tableau PDG</button></div></main>
<script src="/auth.js"></script><script>window.IMC_VAULT_REQUIRED=true;</script><script src="/secure-storage.js"></script>
<script>
(function(){
"use strict";
const KEY="imc_depenses";let source={};let years=[];let audits=[];let backup=false;const $=id=>document.getElementById(id);
function message(text,kind){const e=$("status");e.textContent=text;e.className=kind?"notice "+kind:"";}
function amount(v){if(typeof v!=="number"&&typeof v!=="string")return NaN;let s=String(v).trim().replace(/\s/g,"").replace(/\$/g,"").replace(/HT/gi,"");if(s.includes(".")&&s.includes(","))s=s.replace(/\./g,"").replace(",",".");else if(s.includes(","))s=s.replace(",",".");const n=Number(s);return Number.isFinite(n)&&n>0?Number(n.toFixed(2)):NaN;}
function dateOK(v){if(typeof v!=="string"||!/^\d{4}-\d{2}-\d{2}$/.test(v))return false;const d=new Date(v+"T00:00:00Z");return !Number.isNaN(d.getTime())&&d.toISOString().slice(0,10)===v;}
function rows(){const out=[];Object.entries(source).forEach(([year,list])=>{if(!Array.isArray(list)){out.push({year,id:"",description:"Structure historique invalide",amount:NaN,date:"",valid:false});return;}list.forEach((v,i)=>{if(!v||typeof v!=="object"||Array.isArray(v)){out.push({year,id:"",description:"Entrée illisible "+(i+1),amount:NaN,date:"",valid:false});return;}const id=v.id==null?"":String(v.id).trim(),description=typeof v.description==="string"?v.description.trim():"",n=amount(v.montant??v.amount),date=String(v.date??v.expense_date??"");out.push({year:String(year),id,description,amount:n,date,valid:!!id&&description.length>0&&description.length<=500&&Number.isFinite(n)&&dateOK(date)});});});return out;}
function options(sel){const blank=document.createElement("option");blank.value="";blank.textContent="— Choisir l’année cible —";sel.appendChild(blank);years.forEach(y=>{const o=document.createElement("option");o.value=String(y.id);o.textContent=y.label+" ("+y.status+")";sel.appendChild(o);});}
async function load(){try{const user=await IMCAuth.verifySession();if(!user||!IMCAuth.requirePermission("depenses.reconcile"))throw Error("Accès réservé au PDG autorisé.");await IMCSecureStorage.ready;if(!IMCSecureStorage.isUnlocked())throw Error("Déverrouillez le coffre avant de lire les dépenses historiques.");const raw=localStorage.getItem(KEY),parsed=raw?JSON.parse(raw):{};if(!parsed||typeof parsed!=="object"||Array.isArray(parsed))throw Error("Format historique invalide. Aucune donnée modifiée.");source=parsed;
const [yr,ar]=await Promise.all([fetch("/api/school-years/index.php",{credentials:"same-origin",cache:"no-store"}),fetch("/api/expenses/reconcile.php",{credentials:"same-origin",cache:"no-store"})]);const yp=await yr.json(),ap=await ar.json();if(!yr.ok||!yp.success||!Array.isArray(yp.schoolYears))throw Error(yp.error||"Années scolaires indisponibles.");if(!ar.ok||!ap.success||!Array.isArray(ap.reconciliations))throw Error(ap.error||"Journal d’import indisponible.");years=yp.schoolYears.filter(y=>y.status!=="ARCHIVED");audits=ap.reconciliations;render();}catch(e){$("summary").textContent="Chargement interrompu";message(e.message||"Impossible de lire la source historique.","error");}}
function render(){const all=rows();$("summary").textContent=all.length+" entrée(s) historiques · "+all.filter(r=>r.valid).length+" valide(s) · "+all.filter(r=>!r.valid).length+" à vérifier.";const root=$("records");root.replaceChildren();if(!all.length){root.textContent="Aucune dépense historique trouvée sous imc_depenses.";return;}
all.forEach(r=>{const card=document.createElement("article");card.className="record";const h=document.createElement("h3");h.textContent="Source "+r.year+" · identifiant "+(r.id||"(absent)");card.appendChild(h);const p=document.createElement("p");p.className="meta";p.textContent=r.description+" · "+(Number.isFinite(r.amount)?r.amount.toLocaleString("fr-FR",{minimumFractionDigits:2,maximumFractionDigits:2}):"Montant illisible")+" · "+r.date;card.appendChild(p);
if(!r.valid){const warn=document.createElement("p");warn.className="notice error";warn.textContent="Entrée incomplète ou illisible : import bloqué. Vérifiez la sauvegarde et les archives; aucune valeur ne sera inventée.";card.appendChild(warn);root.appendChild(card);return;}
const done=audits.find(a=>String(a.source_year_label)===r.year&&String(a.source_legacy_id)===r.id);if(done){const ok=document.createElement("p");ok.className="notice success";ok.textContent="Déjà rapprochée vers "+done.target_school_year_label+". Source locale conservée.";card.appendChild(ok);root.appendChild(card);return;}
const row=document.createElement("div");row.className="row";const label=document.createElement("label");label.textContent="Année scolaire cible PostgreSQL";const sel=document.createElement("select");options(sel);row.append(label,sel);card.appendChild(row);
const btn=document.createElement("button");btn.type="button";btn.textContent="Confirmer l’import";btn.disabled=true;sel.addEventListener("change",()=>btn.disabled=!backup||!sel.value);
btn.addEventListener("click",async()=>{if(!backup||!sel.value)return;const target=years.find(y=>String(y.id)===sel.value);if(!target||!confirm("Importer cette dépense de "+r.year+" vers "+target.label+" ? La source locale restera inchangée."))return;btn.disabled=true;try{const csrf=IMCAuth.getCsrfToken();if(!csrf)throw Error("Jeton CSRF absent; reconnectez-vous.");const res=await fetch("/api/expenses/reconcile.php",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json","X-CSRF-Token":csrf},body:JSON.stringify({source_year_label:r.year,legacy_id:r.id,target_school_year_id:target.id,description:r.description,amount:r.amount,expense_date:r.date})});const data=await res.json();if(!res.ok||!data.success)throw Error(data.error||"Import refusé.");const refreshed=await fetch("/api/expenses/reconcile.php",{credentials:"same-origin",cache:"no-store"}),audit=await refreshed.json();if(!refreshed.ok||!audit.success)throw Error(audit.error||"Rafraîchissement de l’audit impossible.");audits=audit.reconciliations;message(data.created?"Dépense importée et journalisée. Source locale conservée.":"Dépense déjà importée; aucun doublon créé. Source locale conservée.","success");render();}catch(e){message(e.message||"Import impossible. Source locale conservée.","error");btn.disabled=!backup||!sel.value;}});
const actions=document.createElement("div");actions.className="actions";actions.appendChild(btn);card.appendChild(actions);root.appendChild(card);});}
$("exportBackup").addEventListener("click",()=>{try{if(!IMCSecureStorage.isUnlocked())throw Error("Le coffre est verrouillé.");const data={format:"clarodaro-expenses-backup-v1",exportedAt:new Date().toISOString(),storageKey:KEY,records:source};const blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="clarodaro-depenses-historiques-"+new Date().toISOString().slice(0,10)+".json";document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$("confirmBackup").disabled=false;$("backupNotice").textContent="Sauvegarde générée. Vérifiez le fichier puis confirmez.";message("Sauvegarde générée. Aucun import avant confirmation.","success");}catch(e){message(e.message||"Sauvegarde impossible.","error");}});
$("confirmBackup").addEventListener("change",e=>{backup=e.target.checked;$("backupNotice").textContent=backup?"Sauvegarde confirmée. Chaque import exige encore une année cible et une confirmation.":"Sauvegarde non confirmée : imports désactivés.";render();});
load();
})();
</script></body></html>
